-- The policy pages, and About, take the site's own texts (worker/src/content/pageTexts.ts — written for the academy from the owner's
-- MAWAH policies) where the short stand-ins the first install put in `settings` are still there word for word: removing them lets the
-- defaults show (lib/settings.ts). Anything the owner wrote is left as it is: each pair goes only if both languages are untouched.
UPDATE settings SET value = json_remove(value, '$.refund_bn', '$.refund_en') WHERE key = 'policies' AND json_extract(value, '$.refund_bn') = 'আমাদের রিফান্ড নীতি শীঘ্রই এখানে প্রকাশ করা হবে। কেনার আগে কোনো প্রশ্ন থাকলে অনুগ্রহ করে আমাদের সাথে যোগাযোগ করুন।' AND json_extract(value, '$.refund_en') = 'Our refund policy will be published here soon. If you have any question before buying, please contact us first.';
UPDATE settings SET value = json_remove(value, '$.privacy_bn', '$.privacy_en') WHERE key = 'policies' AND json_extract(value, '$.privacy_bn') = 'আমরা শুধু ক্লাস সরবরাহ, পেমেন্ট যাচাই এবং সহায়তার জন্য আপনার নাম, ইমেইল ও ফোন নম্বর ব্যবহার করি। আপনার তথ্য তৃতীয় পক্ষের কাছে বিক্রি করা হয় না।' AND json_extract(value, '$.privacy_en') = 'We use your name, email and phone number only to deliver classes, verify payments and give support. We never sell your data to third parties.';
UPDATE settings SET value = json_remove(value, '$.terms_bn', '$.terms_en') WHERE key = 'policies' AND json_extract(value, '$.terms_bn') = 'ক্লাসের কনটেন্ট শুধুমাত্র ভর্তি হওয়া শিক্ষার্থীর ব্যক্তিগত শেখার জন্য। অনুমতি ছাড়া ভিডিও বা রেসিপি শেয়ার, বিক্রি বা পুনঃপ্রকাশ করা যাবে না।' AND json_extract(value, '$.terms_en') = 'Class content is for the personal learning of the enrolled student only. Videos and recipes may not be shared, resold or republished without permission.';
UPDATE settings SET value = json_remove(value, '$.bn', '$.en') WHERE key = 'about' AND json_extract(value, '$.bn') = 'মাওয়াহ একাডেমি রান্না ও বেকিংয়ের একটি অনলাইন একাডেমি। আমাদের ক্লাসগুলো ঘরে বসে ধাপে ধাপে শেখার জন্য সাজানো — কেক, মিষ্টি, ফাস্টফুড, বিরিয়ানি থেকে শুরু করে ফ্রোজেন ফুড বিজনেস পর্যন্ত।' AND json_extract(value, '$.en') = 'MAWAH Academy is an online cooking and baking academy. Our classes are arranged so you can learn step by step from home — from cakes, mishti, fast food and biryani to frozen food business.';

-- The contact details the owner asked for on 18 Oct 2026 (the hotline, and the shop's e-mail) — only while the ones set on 14 Oct are
-- still there; WhatsApp stays. Admin → Settings → Contact changes them at any time.
UPDATE settings SET value = json_set(value, '$.phone', '09613-754321', '$.email', 'info@mawahbd.com') WHERE key = 'contact' AND json_extract(value, '$.phone') = '+880 13 0405 0584' AND json_extract(value, '$.email') = 'mawahacademy@gmail.com';
